tatus_editing:{en:"editing",da:"redigerer",de:"wird bearbeitet",es:"editando"},status_done:{en:"done",da:"færdig",de:"fertig",es:"listo"},status_error:{en:"error",da:"fejl",de:"Fehler",es:"error"},status_cancelled:{en:"cancelled",da:"annulleret",de:"abgebrochen",es:"cancelado"},clear_done:{en:"Clear completed",da:"Ryd færdige",de:"Erledigte entfernen",es:"Limpiar completados"},clear_all:{en:"Clear all",da:"Ryd alt",de:"Alle entfernen",es:"Limpiar todo"},view_latest:{en:"View latest results",da:"Vis seneste resultater",de:"Neueste Ergebnisse anzeigen",es:"Ver últimos resultados"},clear_warning:{en:"This will permanently remove all completed results. Are you sure?",da:"Dette vil permanent fjerne alle færdige resultater. Er du sikker?",de:"Alle abgeschlossenen Ergebnisse werden dauerhaft entfernt. Bist du sicher?",es:"Esto eliminará permanentemente todos los resultados completados. ¿Estás seguro?"},cancel_task:{en:"Cancel task",da:"Annullér opgave",de:"Auftrag abbrechen",es:"Cancelar tarea"},retry_task:{en:"Retry",da:"Forsøg igen",de:"Erneut versuchen",es:"Reintentar"},retry_failed_chapters:{en:"Retry failed chapters",da:"Forsøg fejlede kapitler igen",de:"Fehlgeschlagene Kapitel wiederholen",es:"Reintentar capítulos fallidos"},partial_failure_title:{en:"Some chapters did not complete cleanly",da:"Nogle kapitler blev ikke gennemført korrekt",de:"Einige Kapitel wurden nicht fehlerfrei abgeschlossen",es:"Algunos capítulos no se completaron correctamente"},partial_failure_body:{en:"These chapters had chunks that failed even after retries and should be re-run",da:"Disse kapitler havde dele, der fejlede selv efter forsøg, og bør køres igen",de:"Diese Kapitel hatten Abschnitte, die auch nach Wiederholungen fehlschlugen und erneut ausgeführt werden sollten",es:"Estos capítulos tuvieron fragmentos que fallaron incluso después de reintentos y deben volver a ejecutarse"},partial_failure_hint:{en:"Edited output for failed chunks falls back to the original text. Analysis output may be incomplete. Re-run the affected chapters from the upload screen.",da:"Redigeret output for fejlede dele falder tilbage til den oprindelige tekst. Analyseoutput kan være ufuldstændigt. Kør de berørte kapitler igen fra upload-skærmen.",de:"Die Ausgabe fehlgeschlagener Abschnitte fällt auf den Originaltext zurück. Analyseergebnisse können unvollständig sein. Führe die betroffenen Kapitel erneut vom Upload-Bildschirm aus.",es:"La salida editada de fragmentos fallidos vuelve al texto original. El resultado del análisis puede estar incompleto. Vuelve a ejecutar los capítulos afectados desde la pantalla de subida."},btn_cancel:{en:"Cancel",da:"Annuller",de:"Abbrechen",es:"Cancelar"},n_pending:{en:"pending",da:"afventer",de:"ausstehend",es:"pendiente"},n_running:{en:"running",da:"kører",de:"läuft",es:"en curso"},n_done:{en:"done",da:"færdige",de:"fertig",es:"listo"},warn_unload:{en:"Editing is in progress. If you leave or refresh now, the queue will be lost.",da:"Redigering er i gang. Forlader du siden, mistes køen.",de:"Bearbeitung läuft. Beim Verlassen oder Neuladen geht die Warteschlange verloren.",es:"La edición está en curso. Si sales o actualizas ahora, la cola se perderá."},sec_review:{en:"Review & Export",da:"Gennemgang & Eksport",de:"Überprüfung & Export",es:"Revisión y exportación"},review_empty:{en:"Nothing here yet — results will appear once you run an edit.",da:"Tomt endnu — resultater vises når du kører en redigering.",de:"Noch nichts hier — Ergebnisse erscheinen nach einer Bearbeitung.",es:"Nada aquí todavía — los resultados aparecerán cuando ejecutes una edición."},accepted:{en:"accepted",da:"accepteret",de:"akzeptiert",es:"aceptado"},no_changes:{en:"no changes",da:"ingen rettelser",de:"keine Änderungen",es:"sin cambios"},accept_all:{en:"Accept all",da:"Acceptér alle",de:"Alle akzeptieren",es:"Aceptar todo"},dismiss_all:{en:"Dismiss all",da:"Afvis alle",de:"Alle ablehnen",es:"Descartar todo"},no_corrections_unit:{en:"No corrections proposed.",da:"Ingen rettelser foreslået.",de:"Keine Korrekturen vorgeschlagen.",es:"No se propusieron correcciones."},skipped_label:{en:"skipped",da:"sprunget over",de:"übersprungen",es:"omitido"},skipped_tooltip:{en:"These corrections were skipped because they touched markdown formatting (headings, bold, italic, links) or were ambiguous (e.g. the original text couldn't be uniquely located). This is a safety measure to avoid corrupting the document structure.",da:"Disse rettelser blev sprunget over fordi de berørte markdown-formattering (overskrifter, fed, kursiv, links) eller var tvetydige (f.eks. kunne originalteksten ikke entydigt lokaliseres). Dette er en sikkerhedsforanstaltning for at undgå at ødelægge dokumentstrukturen.",de:"Diese Korrekturen wurden übersprungen, weil sie Markdown-Formatierung (Überschriften, Fett, Kursiv, Links) betrafen oder mehrdeutig waren (z. B. konnte der Originaltext nicht eindeutig lokalisiert werden). Dies ist eine Sicherheitsmaßnahme zum Schutz der Dokumentstruktur.",es:"Estas correcciones se omitieron porque tocaban formato markdown (encabezados, negrita, cursiva, enlaces) o eran ambiguas (p. ej., el texto original no se pudo localizar de forma única). Es una medida de seguridad para evitar corromper la estructura del documento."},output_reflects:{en:"Output reflects",da:"Output afspejler",de:"Ausgabe enthält",es:"La salida refleja"},of:{en:"of",da:"af",de:"von",es:"de"},proposed_changes:{en:"proposed change(s).",da:"foreslåede rettelse(r).",de:"vorgeschlagene Änderung(en).",es:"cambio(s) propuesto(s)."},converting_docx:{en:"Converting to DOCX…",da:"Konverterer til DOCX…",de:"Wird in DOCX konvertiert…",es:"Convirtiendo a DOCX…"},docx_fail:{en:"DOCX conversion failed",da:"DOCX-konvertering mislykkedes",de:"DOCX-Konvertierung fehlgeschlagen",es:"La conversión a DOCX falló"},preview_md:{en:"Preview edited Markdown",da:"Forhåndsvisning af redigeret Markdown",de:"Bearbeitetes Markdown anzeigen",es:"Vista previa del Markdown editado"},results_for:{en:"Results for",da:"Resultater for",de:"Ergebnisse für",es:"Resultados para"},ollama_warning:{en:"No local models found — download one from setup.",da:"Ingen lokale modeller fundet — download én fra opsætning.",de:"Keine lokalen Modelle gefunden — lade eines von der Einrichtung herunter.",es:"No se encontraron modelos locales — descarga uno desde configuración."},retry:{en:"Retry",da:"Prøv igen",de:"Erneut versuchen",es:"Reintentar"},download_md:{en:"Download Markdown",da:"Download Markdown",de:"Markdown herunterladen",es:"Descargar Markdown"},download_docx:{en:"Download DOCX",da:"Download DOCX",de:"DOCX herunterladen",es:"Descargar DOCX"},download_diff:{en:"Download diff report",da:"Download diff-rapport",de:"Diff-Bericht herunterladen",es:"Descargar informe de diferencias"},model_section_title:{en:"Models",da:"Modeller",de:"Modelle",es:"Modelos"},model_needed_banner:{en:"No AI model installed — open Models below to download one before editing.",da:"Ingen AI-model installeret — åbn Modeller herunder for at downloade én før redigering.",de:"Kein KI-Modell installiert — öffne Modelle unten, um eines herunterzuladen.",es:"No hay modelo de IA instalado — abre Modelos abajo para descargar uno antes de editar."},model_setup_title:{en:"Choose a model",da:"Vælg en model",de:"Modell auswählen",es:"Elegir un modelo"},model_setup_desc:{en:"Bethaniel runs AI locally — your manuscripts never leave your computer. Download a model to get started.",da:"Bethaniel kører AI lokalt — dine manuskripter forlader aldrig din computer. Download en model for at komme i gang.",de:"Bethaniel führt KI lokal aus — deine Manuskripte verlassen nie deinen Computer. Lade ein Modell herunter, um loszulegen.",es:"Bethaniel ejecuta IA localmente — tus manuscritos nunca salen de tu ordenador. Descarga un modelo para comenzar."},model_requires:{en:"Requires",da:"Kræver",de:"Benötigt",es:"Requiere"},model_your_machine:{en:"your machine has",da:"din maskine har",de:"dein Rechner hat",es:"tu equipo tiene"},model_i